    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0


submenu_cursor_sprite_layer_bank_table:
    db 0
    db 0
    db 0
    db 0
    db 0
    db 0
    db 0
    db 0
