submenu_cursor_sprite_layer_resource_table:
    db RESOURCE_ID_HERO1_RIGHT_0_F0_LAYER0
    db RESOURCE_ID_HERO1_RIGHT_0_F0_LAYER2
    db RESOURCE_ID_HERO1_RIGHT_0_F0_LAYER3
