; ==================================================================
; SCREEN EDGE TRANSITION RUNTIME
; ==================================================================
; Checks controllable entity exits and transitions world screen.
; Prevents X/Y byte wrap from keeping player in same screen.
; ==================================================================

check_world_screen_transition:
    ; Debounce to prevent immediate re-trigger after crossing
    ld a, (screen_transition_cooldown)
    or a
    jr z, .find_player_start
    dec a
    ld (screen_transition_cooldown), a
    ret

    ; Find first controllable entity from active list (already filtered by screen)
    ; This avoids scanning all 32 entity slots every frame.
.find_player_start:
    ld a, (active_entity_count)
    or a
    ret z
    ld b, a
    ld hl, active_entity_list
.find_player_loop:
    ; E = entity index from compact active list
    ld e, (hl)
    inc hl
    ld d, 0

    ; Check Input component mask
    push hl
    ld hl, entity_comp_masks
    add hl, de
    ld a, (hl)
    and COMP_MASK_INPUT
    pop hl
    jr nz, .player_found

.find_player_next:
    djnz .find_player_loop
    ret                        ; No controllable entity found

.player_found:
    ld d, 0                    ; DE = player entity index

.dispatch_world:
    ld a, (current_world_id)
    cp WORLD_MON_INICIAL_ID
    jp z, check_transition_world_worldmap_1754825914797
    cp WORLD_MON_AUTOGENERAT1_ID
    jp z, check_transition_world_worldmap_1755255512987
    ret

check_transition_world_worldmap_1754825914797:
    ld a, (current_screen_index)
    cp 0
    jp z, check_transition_worldmap_1754825914797_screen_0
    cp 1
    jp z, check_transition_worldmap_1754825914797_screen_1
    cp 2
    jp z, check_transition_worldmap_1754825914797_screen_2
    cp 3
    jp z, check_transition_worldmap_1754825914797_screen_3
    cp 4
    jp z, check_transition_worldmap_1754825914797_screen_4
    cp 5
    jp z, check_transition_worldmap_1754825914797_screen_5
    cp 6
    jp z, check_transition_worldmap_1754825914797_screen_6
    cp 7
    jp z, check_transition_worldmap_1754825914797_screen_7
    cp 8
    jp z, check_transition_worldmap_1754825914797_screen_8
    ret

