    ; West exit: X near left edge and leftward input
    ld a, (input_state)
    cp STICK_LEFT
    jr z, .dir_ok_check_transition_worldmap_1754825914797_s0_skip_west
    cp STICK_UPLEFT
    jr z, .dir_ok_check_transition_worldmap_1754825914797_s0_skip_west
    cp STICK_DOWNLEFT
