    db 0, 0, 0 ; Sprite 8: blackDuck_right

; ==================================================================
; SPRITE INITIALIZATION FUNCTIONS
; ==================================================================

init_sprites:
    ; Copy ROM sprite metadata tables into RAM so gameplay code can read them
    ; without depending on which MegaROM bank is currently mapped.
    ld hl, entity_sprite_config_init
    ld de, entity_sprite_config
    ld bc, 64
    ldir
    ld hl, sprite_asset_frame_count_init
    ld de, sprite_asset_frame_count
    ld bc, 9
    ldir
    ld hl, sprite_asset_layer_count_init
    ld de, sprite_asset_layer_count
    ld bc, 9
    ldir
    ld hl, sprite_loop_flags_init
    ld de, sprite_loop_flags
    ld bc, 9
    ldir
    ld hl, sprite_dir_left_table_init
    ld de, sprite_dir_left_table
    ld bc, 9
    ldir
    ld hl, sprite_dir_right_table_init
    ld de, sprite_dir_right_table
    ld bc, 9
    ldir
    ld hl, sprite_dir_up_table_init
    ld de, sprite_dir_up_table
    ld bc, 9
    ldir
    ld hl, sprite_dir_down_table_init
    ld de, sprite_dir_down_table
    ld bc, 9
    ldir
    ld hl, SM_SpriteLayerColorTable_init
    ld de, SM_SpriteLayerColorTable
    ld bc, 27
    ldir
    ld hl, SM_SpriteLayerYOffsetTable_init
    ld de, SM_SpriteLayerYOffsetTable
    ld bc, 27
    ldir
    ld hl, entity_sprite_asset_index_init
    ld de, entity_sprite_asset_index
    ld bc, 32
    ldir
    ; Copy sprite_layer_colors_init (ROM) -> sprite_layer_colors (RAM)
    ld hl, sprite_layer_colors_init
    ld de, sprite_layer_colors
    ld bc, 32
    ldir
    ; Copy sprite_layer_y_offsets_init (ROM) -> sprite_layer_y_offsets (RAM)
    ld hl, sprite_layer_y_offsets_init
    ld de, sprite_layer_y_offsets
    ld bc, 32
    ldir
    call call_clear_all_sprites_resident
    ld hl, sprite_asset_base_pattern_slot_runtime
    ld (hl), 0
    ld de, sprite_asset_base_pattern_slot_runtime+1
    ld bc, 8
    ldir
    xor a
    ld (sprite_placeholder_base_pattern_num), a
    ld a, #FF
    ld (current_sprite_pattern_pack_id), a
    xor a
    ld (active_sprite_count), a
    ret

load_sprite_patterns:
    call load_sprite_patterns_worldmap_1754825914797
    ret


SPRITE_PATTERN_PACK_INVALID EQU #FF
SPRITE_PATTERN_PACK_COUNT EQU 2

; World index -> runtime sprite pattern pack id
world_sprite_pattern_pack_table:
    db SPRITE_PATTERN_PACK_WORLDMAP_1754825914797_ID ; World 0: Mon Inicial
    db SPRITE_PATTERN_PACK_WORLDMAP_1755255512987_ID ; World 1: Mon autogenerat1

; ------------------------------------------------------------------
; Runtime Sprite Pattern Pack: World "Mon Inicial"
; Slots required: 64/64
; ------------------------------------------------------------------
SPRITE_PATTERN_PACK_WORLDMAP_1754825914797_ID EQU 0

sprite_asset_base_pattern_slot_worldmap_1754825914797:
    db 0 ; Sprite 0: hero1_right
    db 12 ; Sprite 1: bird1
    db 27 ; Sprite 2: ball1
    db 39 ; Sprite 3: bird2
    db 43 ; Sprite 4: minipotato_right
    db 0 ; Sprite 5: blackDuck_left
    db 47 ; Sprite 6: hero1_left
    db 59 ; Sprite 7: minipotato_left
    db 0 ; Sprite 8: blackDuck_right

load_sprite_patterns_worldmap_1754825914797:
    ld hl, sprite_asset_base_pattern_slot_worldmap_1754825914797
    ld de, sprite_asset_base_pattern_slot_runtime
    ld bc, SPRITE_ASSET_COUNT
    ldir
    ld a, 252
    ld (sprite_placeholder_base_pattern_num), a
    ; Sprite Asset 0: hero1_right frame 0 (3 layers)
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F0_LAYER0
    ld de, SPRPAT + (0 * 32)
    call resource_load_to_vram_by_id
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F0_LAYER2
    ld de, SPRPAT + (1 * 32)
    call resource_load_to_vram_by_id
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F0_LAYER3
    ld de, SPRPAT + (2 * 32)
    call resource_load_to_vram_by_id
    ; Sprite Asset 0: hero1_right frame 1 (3 layers)
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F1_LAYER0
    ld de, SPRPAT + (3 * 32)
    call resource_load_to_vram_by_id
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F1_LAYER2
    ld de, SPRPAT + (4 * 32)
    call resource_load_to_vram_by_id
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F1_LAYER3
    ld de, SPRPAT + (5 * 32)
    call resource_load_to_vram_by_id
    ; Sprite Asset 0: hero1_right frame 2 (3 layers)
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F2_LAYER0
    ld de, SPRPAT + (6 * 32)
    call resource_load_to_vram_by_id
    ld a, RESOURCE_ID_HERO1_RIGHT_0_F2_LAYER2
